create extension if not exists pgcrypto;
create table profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,age int,height_cm numeric,current_weight_kg numeric,goal text default 'muscle_gain',diet_preference text default 'mostly_vegetarian',protein_target_g numeric default 95,calorie_target_kcal numeric default 2200,max_eggs_per_day int default 4,vegetarian_days text[] default array['tuesday'],excluded_meals text[] default array['dal_lunch','dal_dinner'],created_at timestamptz default now(),updated_at timestamptz default now());
create table meals(id uuid primary key default gen_random_uuid(),name text not null,meal_type text not null,diet_type text not null,ingredients jsonb default '[]',recipe_steps jsonb default '[]',calories numeric default 0,protein_g numeric default 0,carbs_g numeric default 0,fat_g numeric default 0,fibre_g numeric default 0,gut_risk text default 'medium',active boolean default true);
create table meal_plans(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,week_start date not null,status text default 'active',created_at timestamptz default now(),unique(user_id,week_start));
create table meal_plan_items(id uuid primary key default gen_random_uuid(),plan_id uuid references meal_plans(id) on delete cascade,meal_date date not null,slot text not null,meal_id uuid references meals(id),unique(plan_id,meal_date,slot));
create table meal_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,meal_plan_item_id uuid references meal_plan_items(id),log_date date not null,status text check(status in ('done','partial','missed')),quantity_multiplier numeric default 1,note text,created_at timestamptz default now());
create table daily_journals(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,journal_date date not null,gas_score int,pain_score int,bowel_status text,energy_score int,stress_score int,weight_kg numeric,note text,created_at timestamptz default now(),unique(user_id,journal_date));
create table whoop_uploads(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,file_name text not null,storage_path text,period_start date,period_end date,processed_at timestamptz,status text default 'uploaded',created_at timestamptz default now());
create table whoop_daily_metrics(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,metric_date date not null,recovery_score numeric,hrv_ms numeric,resting_hr_bpm numeric,sleep_minutes int,sleep_performance numeric,sleep_debt_minutes int,sleep_consistency numeric,deep_sleep_minutes int,rem_sleep_minutes int,strain numeric,calories_burned numeric,raw jsonb default '{}',unique(user_id,metric_date));
create table weight_logs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,log_date date not null,weight_kg numeric not null,source text default 'manual',unique(user_id,log_date));
create table health_insights(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,insight_date date not null,category text not null,title text not null,body text not null,evidence jsonb default '{}',severity text default 'info',created_at timestamptz default now());
create table grocery_lists(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,week_start date not null,items jsonb default '[]',unique(user_id,week_start));
